def semver_sort(versions):
    def parse_ident(ident):
        if ident.isdigit():
            return (0, int(ident))
        else:
            return (1, ident)

    def make_key(v):
        core_and_pre = v.split('+', 1)[0]
        if '-' in core_and_pre:
            core, pre = core_and_pre.split('-', 1)
            has_pre = 0  # 0 means has prerelease, sorts first
            pre_idents = [parse_ident(p) for p in pre.split('.')]
        else:
            core = core_and_pre
            has_pre = 1
            pre_idents = []
        major, minor, patch = (int(x) for x in core.split('.'))
        return (major, minor, patch, has_pre, pre_idents)

    return sorted(versions, key=make_key)

